(x, y, t) => {
  let u = 0, v = 0, w = 0;
  for (let i = 0; i < 9; i++) {
    let ph = i * 0.6981;
    let cx = 240 + 190 * Math.sin(t * 0.11 + ph);
    let cy = 120 + 85 * Math.cos(t * 0.08 + ph * 1.4);
    let dx = x - cx, dy = y - cy;
    let d = Math.sqrt(dx * dx + dy * dy);
    u += Math.exp(-d * 0.0025) * Math.sin(d * 0.11 - t * 1.1 + ph);
    v += Math.exp(-d * 0.002) * Math.sin(d * 0.075 + t * 0.6 + ph * 0.6);
    w += Math.exp(-d * 0.003) * Math.cos(d * 0.09 - t * 0.4 + ph * 1.2);
  }
  let ru = Math.tanh(u * 1.8);
  let rv = Math.tanh(v * 1.8);
  let rw = Math.tanh(w * 1.5);
  let p1 = Math.tanh((ru * ru - rv * rv + 0.25 * rw) * 2.2);
  let p2 = Math.tanh((ru * rv + 0.4 * rw - 0.15 * Math.sin(t * 0.3)) * 2.0);
  let p3 = Math.tanh((rw - ru * rv * 0.5) * 1.8);
  let h = (p1 * 0.15 + p2 * 0.1 + 0.52 + 0.03 * Math.sin(p3 * 4.0)) % 1;
  let s = 0.55 + 0.4 * Math.abs(p1);
  let l = 0.18 + 0.32 * (0.5 + 0.5 * p1) + 0.12 * Math.abs(p2) + 0.08 * (0.5 + 0.5 * p3);
  let c = (1 - Math.abs(2 * l - 1)) * s;
  let hh = h * 6, xx = c * (1 - Math.abs(hh % 2 - 1)), m = l - c * 0.5;
  let r, g, b;
  if (hh < 1) { r = c; g = xx; b = 0; }
  else if (hh < 2) { r = xx; g = c; b = 0; }
  else if (hh < 3) { r = 0; g = c; b = xx; }
  else if (hh < 4) { r = 0; g = xx; b = c; }
  else if (hh < 5) { r = xx; g = 0; b = c; }
  else { r = c; g = 0; b = xx; }
  return [Math.min(1, r + m + 0.02 * p3), Math.min(1, g + m + 0.01 * p2), Math.min(1, b + m + 0.03 * p1)];
}
